/* jobs from Villager up to the current job: their skills are all kept */
function jobChain(id = S.job){ const out = []; for (let j = id; j; j = JOBS[j].parent) out.unshift(j); return out; }
const ownedSkillIds = () => jobChain().flatMap(j => JOBS[j].skills);
const tierPoints = j => JOBS[j].jobMax - 1;

const pct = v => `${Math.round(v * 100)}%`;
